const D={up:[0,1],down:[0,-1],left:[-1,0],right:[1,0]};
const s45=Math.SQRT1_2;
const Q={up:[-s45,0,0,s45],down:[s45,0,0,s45],left:[0,0,s45,s45],right:[0,0,-s45,s45]};
const px=c=>(c-1)*1.1,pz=r=>(1-r)*1.1;
const dist=s=>(2-s.c)+(2-s.r);
export function initialState(){return{c:0,r:0,moves:0,hint:null,msg:'Reach the gold Goal square.'};}
export function reduce({state,event}){
if(event.type!=='action')return state;
const a=event.action,s={...state};
if(dist(s)===0){s.msg='You already won in '+s.moves+' moves. Press Reset to play again.';return s;}
if(a==='hint'){s.hint=s.c<2?'right':'up';s.msg='Hint: move '+s.hint+' to get one step closer.';return s;}
const d=D[a];if(!d)return state;
const c=s.c+d[0],r=s.r+d[1];
if(c<0||c>2||r<0||r>2){s.msg='Can\'t move '+a+': that would leave the board.';return s;}
s.c=c;s.r=r;s.moves++;s.hint=null;
const k=dist(s);
s.msg=k===0?(s.moves===4?'You won in 4 moves, the shortest possible route!':'You won in '+s.moves+' moves. The shortest route is 4 moves.'):'Moved '+a+'. '+k+' step'+(k===1?'':'s')+' to go.';
return s;}
export function evaluate({state}){
const s=state||initialState();
const x=px(s.c),z=pz(s.r),k=dist(s);
const y=k===0?0.51:0.45;
const nodes={tokenN:{position:[x,y,z]},hintA:{visible:!!s.hint&&k>0,position:[x,y,z]}};
if(s.hint)nodes.hintA.quaternion=Q[s.hint];
return{nodes,readouts:{moves:s.moves,dist:k},goal:{status:k===0?'won':'playing',message:s.msg}};}
